class.ioread:

const auto N = newObj->fSoALayout.fX.size(); // all columns have the same length
newObj->fMemory = std::make_unique<std::byte[]>(N * sizeof(SoAPoint::UnderlyingRecord));
std::memcpy(newObj->fMemory.get(), newObj->fSoALayout.fX.data(), sizeof(float) * N);
std::memcpy(newObj->fMemory.get() + sizeof(float) * N, newObj->fSoALayout.fY.data(), sizeof(float) * N);
newObj->fSoALayout.fX = ROOT::RVec<float>(reinterpret_cast<float *>(newObj->fMemory.get()), N);
newObj->fSoALayout.fY = ROOT::RVec<float>(reinterpret_cast<float *>(newObj->fMemory.get() + sizeof(float) * N), N);
